<div class="relatorio-header"><h1 class="relatorio-titulo">Histórico de importações</h1><a class="btn btn-primary" href="<?=URL_BASE?>/importacao/index">Nova importação</a></div><div class="relatorio-tabela"><table><thead><tr><th>Ficheiro</th><th>Data</th><th>Importadas</th><th>Falhadas</th><th>Tempo</th><th></th></tr></thead><tbody><?php foreach($importacoes as $i):?><tr><td><?=htmlspecialchars($i['nome_arquivo'])?></td><td><?=htmlspecialchars($i['criado_em'])?></td><td><?=$i['linhas_importadas']?></td><td><?=$i['linhas_falhadas']?></td><td><?=$i['tempo_processamento_ms']?> ms</td><td><?php if($i['status']==='concluida'):?><form method="post" action="<?=URL_BASE?>/importacao/reverter/<?=$i['id']?>"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf_token)?>"><button class="btn btn-outline btn-sm">Reverter</button></form><?php endif?></td></tr><?php endforeach?></tbody></table></div>
